// ============================================================================
// PLAN POSTS  (Code node, mode: Run Once for All Items)
// Input: rows of the "Posts" tab. Also reads the "Settings" tab.
// 1. Gives every new topic a Post ID and the earliest free posting date
//    on the "every N days" pattern (one post per date).
// 2. Marks rows whose posting date is close enough to be written by AI now,
//    and rows a person set to REGENERATE.
// Output: only rows that changed or must be generated (field _generate).
// ============================================================================

const settings = {};
for (const item of $('Read Settings').all()) {
  const key = String(item.json['Setting'] ?? '').trim();
  if (key) settings[key] = String(item.json['Value'] ?? '').trim();
}

const tz = settings['Timezone'] || 'Asia/Kolkata';
const everyNDays = Math.max(1, parseInt(settings['Post Every N Days'] || '4', 10) || 4);
const defaultTime = /^\d{1,2}:\d{2}$/.test(settings['Default Post Time'] || '') ? settings['Default Post Time'] : '18:00';
const leadDays = Math.max(0, parseInt(settings['Generate Days Before'] || '3', 10) || 0);
const today = DateTime.now().setZone(tz).startOf('day');

function parseDate(value) {
  const text = String(value ?? '').trim();
  if (!text) return null;
  let d = DateTime.fromISO(text, { zone: tz });                    // 2026-10-05
  if (!d.isValid) d = DateTime.fromFormat(text, 'd/M/yyyy', { zone: tz }); // 05/10/2026 (day first)
  if (!d.isValid) d = DateTime.fromFormat(text, 'd-M-yyyy', { zone: tz });
  return d.isValid ? d.startOf('day') : null;
}

const startDate = parseDate(settings['Start Date']) || today;

// First date on the "every N days" grid (counted from Start Date) that is >= minDate.
function nextGridDate(minDate) {
  if (minDate <= startDate) return startDate;
  const daysFromStart = Math.floor(minDate.diff(startDate, 'days').days + 1e-9);
  const steps = Math.ceil(daysFromStart / everyNDays);
  let d = startDate.plus({ days: steps * everyNDays });
  if (d < minDate) d = d.plus({ days: everyNDays });
  return d;
}

const rows = $input.all().map((item) => ({ ...item.json }));

// Highest existing Post ID number (P0001, P0002, ...)
let maxId = 0;
for (const row of rows) {
  const m = String(row['Post ID'] ?? '').match(/(\d+)/);
  if (m) maxId = Math.max(maxId, parseInt(m[1], 10));
}

// Dates already taken by a post (one post per date)
const taken = new Set();
for (const row of rows) {
  const d = parseDate(row['Scheduled Date']);
  if (d && String(row['Topic'] ?? '').trim()) taken.add(d.toISODate());
}

// Earliest free date on the "every N days" grid, from today onwards.
function nextFreeDate() {
  let d = nextGridDate(today);
  while (taken.has(d.toISODate())) d = d.plus({ days: everyNDays });
  taken.add(d.toISODate());
  return d;
}

const output = [];
for (const row of rows) {
  const topic = String(row['Topic'] ?? '').trim();
  if (!topic) continue;
  let status = String(row['Status'] ?? '').trim().toUpperCase();
  let changed = false;

  if (status === '' || status === 'NEW') {
    if (!String(row['Post ID'] ?? '').trim()) {
      maxId += 1;
      row['Post ID'] = 'P' + String(maxId).padStart(4, '0');
    }
    let date = parseDate(row['Scheduled Date']);
    if (!date) date = nextFreeDate();
    row['Scheduled Date'] = date.toISODate();
    if (!String(row['Post Time'] ?? '').trim()) row['Post Time'] = defaultTime;
    status = 'PLANNED';
    row['Status'] = status;
    changed = true;
  }

  const date = parseDate(row['Scheduled Date']);
  const dueForWriting = status === 'PLANNED' && date && date.diff(today, 'days').days <= leadDays;
  const generate = status === 'REGENERATE' || Boolean(dueForWriting);

  if (changed || generate) {
    row['Last Updated'] = DateTime.now().setZone(tz).toFormat('yyyy-MM-dd HH:mm');
    output.push({ json: { ...row, _generate: generate } });
  }
}

return output;

// ============================================================================
// BUILD AI REQUEST  (Code node, mode: Run Once for Each Item)
// Builds the request that asks the AI to write one Instagram post.
// The AI must NOT invent prices, dates, claims etc. - only facts from the
// "Settings" tab (Verified Facts) and the row's "Important Info" may be used.
// ============================================================================

const settings = {};
for (const item of $('Read Settings').all()) {
  const key = String(item.json['Setting'] ?? '').trim();
  if (key) settings[key] = String(item.json['Value'] ?? '').trim();
}
const config = $('Config').first().json;
const row = $json;

const brand = [
  ['Company name', settings['Company Name']],
  ['About the company', settings['Company Description']],
  ['Usual audience', settings['Target Audience']],
  ['Brand voice / tone', settings['Brand Voice']],
  ['Words to avoid', settings['Words To Avoid']],
  ['Hashtags we always like to use', settings['Default Hashtags']],
  ['Content rules', settings['Content Rules']],
]
  .filter(([, v]) => v)
  .map(([k, v]) => `- ${k}: ${v}`)
  .join('\n');

const system = `You are an expert Instagram content writer for a company. Write ORIGINAL, engaging, on-brand posts.

STRICT FACT RULES (these override everything else):
- Never invent prices, fees, discounts, dates, exam dates, deadlines, course details, results, rankings,
  statistics, guarantees, testimonials, names, phone numbers, emails, addresses or links.
- You may only state such a fact if it appears in VERIFIED FACTS or in POST DETAILS below.
- If a fact is needed but missing, leave it out (or write a placeholder like [EXAM DATE]) and list what is
  missing in "missing_information".
- Never promise outcomes ("guaranteed selection", "100% results") unless that exact claim is a verified fact.

Return JSON only:
- headline: max ~8 words, no hashtags
- caption: the Instagram caption WITHOUT hashtags, under 1800 characters, with line breaks, call to action near the end
- hashtags: 8-20 hashtags without the # sign
- image_prompt: a detailed description of an image for an image generator. The image must contain NO text, letters, numbers or logos.
- missing_information: list of facts a human must add or check (empty list if none)`;

const user = `BRAND:
${brand || '- (not filled in yet)'}

VERIFIED FACTS (the only facts you may state):
${settings['Verified Facts'] || '- none - do not state any specific facts, prices or dates'}

POST DETAILS:
- Topic: ${row['Topic'] || ''}
- Category: ${row['Category'] || 'General'}
- Target audience: ${row['Target Audience'] || settings['Target Audience'] || ''}
- Important information: ${row['Important Info'] || '(none)'}
- Call to action: ${row['Call To Action'] || '(choose a suitable one, without inventing offers)'}
- Language: ${settings['Language'] || 'English'}
${row['Status'] === 'REGENERATE' && row['Review Notes'] ? `\nThe previous version was rejected. Reviewer notes: ${row['Review Notes']}` : ''}
Visual style for the image: ${settings['Visual Style'] || 'clean, modern, friendly'}`;

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['headline', 'caption', 'hashtags', 'image_prompt', 'missing_information'],
  properties: {
    headline: { type: 'string' },
    caption: { type: 'string' },
    hashtags: { type: 'array', items: { type: 'string' } },
    image_prompt: { type: 'string' },
    missing_information: { type: 'array', items: { type: 'string' } },
  },
};

return {
  json: {
    ...row,
    _openai: {
      model: config.textModel,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
      response_format: { type: 'json_schema', json_schema: { name: 'instagram_post', strict: true, schema } },
    },
  },
};

// ============================================================================
// CHECK AI TEXT  (Code node, mode: Run Once for Each Item)
// Reads the AI answer, validates it against Instagram's rules, and flags any
// price / date / percentage / phone / guarantee etc. that is NOT in the
// verified facts or the post's Important Info (so a human checks it).
// Sets _ok = false if the AI call failed (the row is left for a retry tomorrow).
// ============================================================================

const row = $('Build AI request').item.json;
const response = $json;
const config = $('Config').first().json;
const settings = {};
for (const item of $('Read Settings').all()) {
  const key = String(item.json['Setting'] ?? '').trim();
  if (key) settings[key] = String(item.json['Value'] ?? '').trim();
}

function fail(message) {
  const clean = { ...row };
  delete clean._openai;
  return { json: { ...clean, _ok: false, Error: 'AI writing failed: ' + message } };
}

if (response.error) {
  return fail(typeof response.error === 'string' ? response.error : response.error.message || JSON.stringify(response.error));
}
const message = response.choices && response.choices[0] && response.choices[0].message;
if (!message) return fail('unexpected answer from the AI service');
if (message.refusal) return fail('the AI declined: ' + message.refusal);

let post;
try {
  let text = String(message.content || '').trim();
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fence) text = fence[1];
  post = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
} catch (e) {
  return fail('the answer was not valid JSON');
}

const headline = String(post.headline || '').trim().slice(0, 120);
let caption = String(post.caption || '').trim();
const imagePrompt = String(post.image_prompt || '').trim();
if (!headline || !caption || !imagePrompt) return fail('headline, caption or image prompt was empty');

// Hashtags: no #, no spaces, unique, max 30 (Instagram limit)
const seen = new Set();
const hashtags = [];
for (const raw of [...(post.hashtags || []), ...String(settings['Default Hashtags'] || '').split(/[\s,]+/)]) {
  const tag = String(raw).replace(/^#+/, '').replace(/\s+/g, '').trim();
  if (!tag || !/^[\p{L}\p{N}_]+$/u.test(tag) || seen.has(tag.toLowerCase())) continue;
  seen.add(tag.toLowerCase());
  hashtags.push(tag);
}
const tags = hashtags.slice(0, 30);
const hashtagText = tags.map((t) => '#' + t).join(' ');
const maxCaption = 2200 - (hashtagText ? hashtagText.length + 2 : 0);
const notes = [];
if (caption.length > maxCaption) {
  caption = caption.slice(0, maxCaption - 1) + '…';
  notes.push('Caption was shortened to fit Instagram\'s 2,200 character limit.');
}

// ---- Fact guard -----------------------------------------------------------
const sources = [settings['Verified Facts'], settings['Company Name'], settings['Website'], settings['Contact Info'], row['Important Info'], row['Topic'], row['Call To Action']]
  .filter(Boolean)
  .join('\n');
const sourceLower = sources.toLowerCase();
const sourceDigits = sourceLower.replace(/[₹$€£,\s]|rs\.?|inr/g, '');
const months = '(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)';
const checks = [
  ['Price', /(?:₹|rs\.?|inr|\$|usd|€|£)\s?\d[\d,]*(?:\.\d+)?|\d[\d,]*(?:\.\d+)?\s?(?:rupees|\/-|lakhs?|crores?)/gi],
  ['Percentage', /\d+(?:\.\d+)?\s?%|\d+(?:\.\d+)?\s?percent/gi],
  ['Date', new RegExp(`\\b\\d{1,2}(?:st|nd|rd|th)?\\s+${months}\\b(?:,?\\s+\\d{4})?|\\b${months}\\s+\\d{1,2}(?:st|nd|rd|th)?\\b|\\b\\d{1,2}[/-]\\d{1,2}[/-]\\d{2,4}\\b`, 'gi')],
  ['Phone number', /(?:\+\d{1,3}[\s-]?)?(?:\d[\s-]?){10,12}\b/g],
  ['Email', /[\w.+-]+@[\w-]+\.[\w.-]+/g],
  ['Link', /https?:\/\/\S+|www\.\S+/gi],
  ['Offer / discount', /\b(?:\d+\s?%\s?off|flat\s+\d+|discount|free\s+(?:class|course|trial|demo)|scholarship|offer\s+ends?)\b/gi],
  ['Guarantee / absolute claim', /\b(?:guarantee[ds]?|100\s?%|assured|sure[- ]shot|no\.?\s?1|number\s+one|best\s+in|top\s+ranked)\b/gi],
  ['Numeric claim', /\b\d[\d,]*\+?\s+(?:students|selections|toppers|ranks?|years|learners|results|centres|centers|branches)\b/gi],
  ['Placeholder to fill in', /\[[A-Z][A-Z0-9 _/-]{2,40}\]/g],
];
const flags = [];
const textToCheck = [headline, caption].join('\n').replace(/#\w+/g, '');
for (const [label, re] of checks) {
  for (const m of textToCheck.matchAll(re)) {
    const found = m[0].trim();
    const digits = found.toLowerCase().replace(/[₹$€£,\s]|rs\.?|inr/g, '');
    const verified = label !== 'Placeholder to fill in' && (sourceLower.includes(found.toLowerCase()) || (digits && sourceDigits.includes(digits)));
    if (!verified) flags.push(`${label} "${found}" is not in Verified Facts / Important Info - check it.`);
  }
}
for (const missing of post.missing_information || []) {
  if (String(missing).trim()) flags.push('Missing information: ' + String(missing).trim());
}

const clean = { ...row };
delete clean._openai;
return {
  json: {
    ...clean,
    _ok: true,
    Headline: headline,
    Caption: caption,
    Hashtags: tags.join(' '),
    'Review Notes': [...new Set([...flags, ...notes])].join('\n') || 'No issues found - please still read it before approving.',
    Error: '',
    _imageRequest: {
      model: config.imageModel,
      prompt: `${imagePrompt}\nStyle: ${settings['Visual Style'] || 'clean, modern, friendly'}.\nDo not include any text, letters, numbers or logos in the image.`,
      size: '1024x1536',
      n: 1,
    },
  },
};

// ============================================================================
// PREPARE ROW  (Code node, mode: Run Once for Each Item)
// After the image was generated and uploaded to Cloudinary, builds the final
// Instagram-ready image link (JPEG, 1080x1350 = Instagram's 4:5 portrait size)
// and marks the post NEEDS_REVIEW for a human.
// ============================================================================

const row = $('Check AI text').item.json;
const imageAnswer = $('Create image with AI').item.json;
const upload = $json;
const settings = {};
for (const item of $('Read Settings').all()) {
  const key = String(item.json['Setting'] ?? '').trim();
  if (key) settings[key] = String(item.json['Value'] ?? '').trim();
}

const notes = String(row['Review Notes'] || '');
const result = { ...row };
delete result._imageRequest;
delete result._ok;
delete result._generate;

function errorText(r) {
  if (!r || !r.error) return '';
  return typeof r.error === 'string' ? r.error : r.error.message || JSON.stringify(r.error);
}

const imageError = errorText(imageAnswer) || (!(imageAnswer.data && imageAnswer.data[0]) ? 'no image returned' : '') || errorText(upload) || (!upload.secure_url ? 'image upload failed' : '');

if (imageError) {
  result['Image URL'] = '';
  result['Review Notes'] = `IMAGE FAILED: ${imageError}. Set Status to REGENERATE to try again, or paste your own public JPEG link in "Image URL".\n` + notes;
} else {
  // Cloudinary transformation: crop to 4:5, 1080x1350, convert to JPEG (Instagram only accepts JPEG).
  const transform = ['c_fill', 'g_auto', 'w_1080', 'h_1350'];
  let overlay = '';
  if (/^(yes|true|y)$/i.test(settings['Headline On Image'] || '') && row['Headline']) {
    // Optional: write the headline on the image (Cloudinary text overlay).
    const text = encodeURIComponent(String(row['Headline']).slice(0, 80)).replace(/%2C/g, '%252C').replace(/%2F/g, '%252F');
    overlay = `/l_text:Arial_64_bold:${text},co_white,b_rgb:00000099,w_960,c_fit/fl_layer_apply,g_south,y_90`;
  }
  const url = String(upload.secure_url).replace('/upload/', `/upload/${transform.join(',')}${overlay}/f_jpg,q_90/`).replace(/\.(png|webp|jpe?g)$/i, '.jpg');
  result['Image URL'] = url;
}

result['Status'] = 'NEEDS_REVIEW';
result['Error'] = '';
result['Last Updated'] = DateTime.now().setZone(settings['Timezone'] || 'Asia/Kolkata').toFormat('yyyy-MM-dd HH:mm');
return { json: result };
